use function Friends\e;
$canPost=$view==='feed' || ($view==='profile' && (int)$profile['id']===(int)$app->user['id']) || ($view==='community' && $joined && ($community['kind']==='group' || (int)$community['owner_id']===(int)$app->user['id']));
?>
<?php if($canPost) require __DIR__.'/post-composer.php'; ?>
<?php foreach($posts as $post): ?><article class="card post" id="post-<?= (int)$post['id'] ?>"><div class="post-head"><a class="post-avatar-link" aria-label="<?= e($post['name']) ?>" href="<?= e($app->url('profile',['id'=>$post['user_id']])) ?>"><?= (new Friends\Features($app))->avatar((int)$post['user_id'],$post['username'],'post-avatar') ?></a><div><a class="post-author" href="<?= e($app->url('profile',['id'=>$post['user_id']])) ?>"><?= e($post['name']) ?></a><?php if($post['community_name']): ?> <span>→</span> <a href="<?= e($app->url('community',['id'=>$post['community_id']])) ?>"><?= e($post['community_name']) ?></a><?php endif ?><small><time datetime="<?= e(str_replace(' ','T',$post['created_at']).'Z') ?>"><?= e($post['created_at']) ?> UTC</time> · <?= $label($post['visibility']) ?></small></div><span class="post-mark" aria-hidden="true">•••</span></div><p class="post-body"><?= Friends\Links::render($post['body']) ?></p><?php require __DIR__.'/post-attachments.php'; ?><div class="post-stats"><span>♡ <?= (int)$post['likes'] ?></span><span><?= count($post['comments']) ?> <?= $label('comment') ?></span></div><div class="post-actions"><form method="post"><?php $form('like',(int)$post['id']) ?><button class="text-button <?= $post['liked']?'is-liked':'' ?>"><?= $post['liked']?'♥':'♡' ?> <?= $label($post['liked']?'liked':'like') ?></button></form><a href="#comment-<?= (int)$post['id'] ?>">☏ <?= $label('comment') ?></a><details class="post-menu"><summary><?= $label('more') ?></summary><div class="post-menu-content"><?php if((int)$post['user_id']===(int)$app->user['id'] || $app->user['role']==='admin'): ?><form method="post" data-confirm="<?= $label('delete') ?>?"><?php $form('delete_post',(int)$post['id']) ?><button class="text-button danger"><?= $label('delete') ?></button></form><?php endif ?><form method="post" class="stack"><?php $form('report',(int)$post['id']) ?><label><?= $label('reason') ?><input name="reason" required maxlength="500"></label><button class="button soft"><?= $label('report') ?></button></form></div></details></div>
 <div class="comments"><?php foreach($post['comments'] as $comment): ?><div class="comment"><a href="<?= e($app->url('profile',['id'=>$comment['user_id']])) ?>"><strong><?= e($comment['name']) ?></strong></a><p><?= e($comment['body']) ?></p></div><?php endforeach ?><form method="post" class="comment-form"><?php $form('comment',(int)$post['id']) ?><input id="comment-<?= (int)$post['id'] ?>" name="body" required maxlength="2000" placeholder="<?= $label('comment_placeholder') ?>" aria-label="<?= $label('comment_placeholder') ?>"><button class="icon-button" aria-label="<?= $label('comment') ?>">↗</button></form></div></article><?php endforeach ?>
<?php if(!$posts): ?><div class="card empty-state"><span>✳</span><p><?= $label('empty_feed') ?></p></div><?php endif ?>
<nav class="pagination" aria-label="Pagination"><?php $current=max(1,(int)($_GET['page']??1)); $params=array_intersect_key($_GET,array_flip(['id','q'])); if($current>1): ?><a class="button soft" href="<?= e($app->url($app->route,$params+['page'=>$current-1])) ?>">← <?= $label('previous') ?></a><?php endif ?><?php if(count($posts)===20): ?><a class="button soft" href="<?= e($app->url($app->route,$params+['page'=>$current+1])) ?>"><?= $label('next') ?> →</a><?php endif ?></nav>
